 <Dialog open={!!form} onOpenChange={v=>{if(!v)setForm(null)}}><DialogContent showCloseButton={false} className="form-dialog"><DialogClose className="close-panel" aria-label="Cerrar formulario"><X size={17}/></DialogClose><DialogHeader><DialogTitle>{form?.kind==='pay'?'Registrar cobro':form?.kind==='invoice'?'Generar factura':`Guardar ${labels[form?.kind||'companies']}`}</DialogTitle><DialogDescription>Los campos se guardan en el espacio de {data.tenant}.</DialogDescription></DialogHeader>{form&&<RecordForm key={form.record.id} form={form} state={s} busy={busy} error={formError} refresh={load} onSubmit={async(record:any)=>{let cmd:any={action:'save',kind:form.kind,record};if(form.kind==='invoice')cmd={...record,action:'invoice',id:record.orderId};if(form.kind==='editInvoice')cmd={...record,action:'editInvoice'};if(form.kind==='pay')cmd={action:'pay',id:record.invoiceId,date:record.date};if(await send(cmd)){setForm(null);toast.success('Guardado')}}}/>}</DialogContent></Dialog>
