function RecordForm({form,state:s,busy,error,refresh,onSubmit}:{form:Form;state:State;busy:boolean;error:string;refresh:()=>void;onSubmit:(r:any)=>Promise<void>}){
 const [r,setR]=useState<any>(form.record);const k=form.kind;
 const set=(key:string,v:any)=>setR((old:any)=>({...old,[key]:v}));
 const input=(key:string,label:string,type='text',props:any={})=><Field label={label}><input type={type} value={r[key]??''} onChange={e=>set(key,type==='number'?(e.target.value===''?'':Number(e.target.value)):e.target.value)} onInput={e=>{if(type==='date')set(key,e.currentTarget.value)}} {...props}/></Field>;
 const pick=(key:string,label:string,options:any[])=><Field label={label}><Pick value={String(r[key]??'')} onChange={v=>set(key,key==='lineIndex'?Number(v):v)} label={label} options={options}/></Field>;
 const oppOptions=[{value:'',label:'Selecciona una oportunidad'},...s.opportunities.map(o=>({value:o.id,label:`${s.companies.find(c=>c.id===o.companyId)?.name} · ${o.title}`}))];
 const taskOptions=[{value:'',label:'Selecciona una tarea'},...s.delivery.map(t=>({value:t.id,label:`${s.projects.find(p=>p.id===t.projectId)?.title} · ${t.title}`}))];
 const order=s.orders.find(o=>o.id===r.orderId);
 const invoiced=(policy:string)=>s.invoices.filter(i=>i.orderId===order?.id&&i.policy===policy).reduce((a,i)=>a+i.amount,0);
 const eligibleHours=s.hours.filter(h=>{const t=s.delivery.find(t=>t.id===h.taskId);const p=s.projects.find(p=>p.id===t?.projectId);return p?.orderId===order?.id&&order?.lines[t?.lineIndex??-1]?.policy==='hours'&&!s.invoices.some(i=>i.hourIds.includes(h.id))});
 return <form className="record-form" noValidate onSubmit={e=>{e.preventDefault();void onSubmit(r)}}>
 {k==='leads'&&<>{input('name','Empresa o contacto *')}{input('contact','Persona de contacto')}{input('email','Email','email')}{input('phone','Teléfono','tel')}{pick('source','Origen',[...leadSources])}{pick('status','Estado',leadStatuses.filter(status=>status!=='Convertido'||r.status==='Convertido'))}{input('nextDate','Fecha de la próxima acción','date')}<Field label="Qué sabemos"><textarea value={r.notes} onChange={e=>set('notes',e.target.value)} placeholder="Interés, contexto y por qué merece seguimiento"/></Field>{r.status==='Convertido'&&<p className="muted">Este lead ya es una oportunidad. El historial se conserva en la empresa.</p>}</>}
 {k==='companies'&&<>{input('name','Nombre de la empresa *')}{input('contact','Persona de contacto')}{input('email','Email','email')}{input('phone','Teléfono','tel')}{input('contactDays','Días sin contacto para marcar riesgo *','number',{min:1,max:90})}</>}
 {k==='opportunities'&&<>{pick('companyId','Empresa *',[{value:'',label:'Selecciona una empresa'},...s.companies.map(c=>({value:c.id,label:c.name}))])}{input('title','Nombre de la oportunidad *')}{input('amount','Importe estimado (€) *','number',{min:0,step:.01})}{pick('stage','Etapa',[...stages])}{input('closeDate','Fecha de cierre *','date')}{input('nextStep','Siguiente paso')}{input('nextDate','Fecha del siguiente paso','date')}</>}
 {k==='interactions'&&<>{pick('kind','Tipo de contacto',['Llamada','Email','Reunión','Nota'])}{input('date','Fecha *','date')}<Field label="Qué habéis hablado *"><textarea value={r.notes} onChange={e=>set('notes',e.target.value)} autoFocus/></Field></>}
 {k==='followups'&&<>{pick('opportunityId','Oportunidad *',oppOptions)}{input('title','Qué hay que hacer *')}{input('dueDate','Fecha de seguimiento *','date')}</>}
 {(k==='quotes'||k==='orders')&&<>{k==='quotes'?pick('opportunityId','Oportunidad *',oppOptions):pick('quoteId','Presupuesto de origen *',s.quotes.map(q=>({value:q.id,label:q.title})))}{input('title','Nombre del documento *')}<h3>Líneas de servicio</h3>{r.confirmed&&<p className="muted">Pedido confirmado: puedes cambiar su nombre. Sus líneas se conservan para mantener la trazabilidad.</p>}{r.lines.map((l:any,i:number)=>{const patch=(key:string,value:any)=>set('lines',r.lines.map((x:any,n:number)=>n===i?{...x,[key]:value}:x));return <fieldset className="service-line" key={i} disabled={r.confirmed}><legend>Servicio {i+1}</legend><Field label="Descripción del servicio *"><input value={l.description} onChange={e=>patch('description',e.target.value)}/></Field><div className="form-grid"><Field label={l.policy==='hours'?'Horas previstas *':'Cantidad *'}><input type="number" min="0.01" step="0.01" value={l.quantity} onChange={e=>patch('quantity',Number(e.target.value))}/></Field><Field label={l.policy==='hours'?'Precio por hora (€) *':'Precio unitario (€) *'}><input type="number" min="0" step="0.01" value={l.price} onChange={e=>patch('price',Number(e.target.value))}/></Field></div><Field label="Política de facturación"><Pick value={l.policy} onChange={v=>patch('policy',v)} label="Política de facturación" options={Object.entries(policyLabel).map(([value,label])=>({value,label}))}/></Field><Field label="Tareas del proyecto · una por línea *"><textarea value={l.tasks} onChange={e=>patch('tasks',e.target.value)}/></Field>{r.lines.length>1&&<button type="button" className="subtle red" onClick={()=>set('lines',r.lines.filter((_:any,n:number)=>n!==i))}>Quitar servicio</button>}</fieldset>})}<button disabled={r.confirmed} type="button" className="outline" onClick={()=>set('lines',[...r.lines,{description:'',quantity:1,price:0,policy:'fixed',tasks:'Entrega y revisión'}])}><Plus size={14}/> Añadir línea</button><div className="form-total">Total del documento <strong>{eur(total(r.lines))}</strong></div></>}
 {k==='delivery'&&<>{pick('projectId','Proyecto *',s.projects.map(p=>({value:p.id,label:p.title})))}{input('title','Tarea de entrega *')}{pick('lineIndex','Servicio del pedido *',(s.orders.find(o=>o.id===s.projects.find(p=>p.id===r.projectId)?.orderId)?.lines||[]).map((l,i)=>({value:String(i),label:l.description})))}</>}
 {k==='hours'&&<>{pick('taskId','Tarea del proyecto *',taskOptions)}{input('date','Fecha *','date')}{input('hours','Horas imputadas *','number',{min:.01,max:24,step:.25})}{input('cost','Coste interno por hora (€) *','number',{min:0,step:.01})}{input('notes','Trabajo realizado')}<p className="muted">Coste imputado: {eur((Number(r.hours)||0)*(Number(r.cost)||0))}</p></>}
 {(k==='invoice'||k==='editInvoice')&&<>{k==='invoice'&&<><Field label="Pedido confirmado *"><Pick value={r.orderId} onChange={v=>{const o=s.orders.find(o=>o.id===v);setR({...r,orderId:v,policy:o?.lines[0].policy||'fixed',hourIds:[]})}} label="Pedido confirmado" options={[{value:'',label:'Selecciona un pedido'},...s.orders.filter(o=>o.confirmed).map(o=>({value:o.id,label:o.title}))]}/></Field>{pick('policy','Política de facturación',Array.from(new Set(order?.lines.map(l=>l.policy)||[])).map(value=>({value,label:policyLabel[value]})))}</>}{input('title','Número o referencia de factura *')}{input('date','Fecha de emisión *','date')}{input('dueDate','Fecha de vencimiento *','date')}{k==='invoice'&&r.policy==='milestones'&&input('amount','Importe del hito (€) *','number',{min:.01,step:.01})}{k==='invoice'&&r.policy!=='hours'&&<p className="form-total">Pendiente de facturar <strong>{eur(total(order?.lines.filter(l=>l.policy===r.policy)||[])-invoiced(r.policy))}</strong></p>}{k==='invoice'&&r.policy==='hours'&&<><h3>Horas pendientes de facturar</h3>{eligibleHours.map(h=><label className="task-row" key={h.id}><Checkbox checked={r.hourIds.includes(h.id)} onCheckedChange={checked=>set('hourIds',checked?[...r.hourIds,h.id]:r.hourIds.filter((id:string)=>id!==h.id))}/><span>{s.delivery.find(t=>t.id===h.taskId)?.title}<small>{h.date} · {h.hours} h</small></span></label>)}{!eligibleHours.length&&<p className="muted">No hay horas pendientes para este pedido.</p>}</>}</>}
 {k==='pay'&&<><p className="form-total">Cobro completo <strong>{eur(r.amount)}</strong></p>{input('date','Fecha del cobro *','date')}</>}
 {error&&<div className="error" role="alert">{error}<button type="button" className="subtle" onClick={refresh}>Recargar datos conservando el formulario</button></div>}<button className="primary save-button" disabled={busy}>{busy?'Guardando…':k==='invoice'?'Generar factura':k==='pay'?'Registrar cobro':'Guardar'}</button>
 </form>
}
